/** The pieces a message still wants, as up to `cap` ranges each of
 *  at most `most` pieces: `first[k]` and `count[k]`. Answers how
 *  many ranges; 0 where no such message is held. Build the
 *  re-request yourself: it carries your expiry and your seal. */
static inline uint32_t situ_pieces_missing(const situ_pieces_t *t,
		const uint8_t *key,
		uint32_t *first, uint32_t *count, uint32_t cap, uint32_t most)
{
	for (uint32_t s = 0u; s < t->messages; s++) {
		const situ_pieces_slot_t *m = &t->slot[s];
		if (m->live == 0u || memcmp(m->key, key, 36u) != 0) {
			continue;
		}
		uint32_t n = 0u;
		for (uint32_t i = 0u; i < m->count; i++) {
			if (situ_pieces_marked(t, s, i)) {
				continue;
			}
			if (n > 0u && first[n - 1u] + count[n - 1u] == i
			    && count[n - 1u] < most) {
				count[n - 1u]++;
			} else if (n < cap) {
				first[n] = i;
				count[n] = 1u;
				n++;
			} else {
				break;
			}
		}
		return n;
	}
	return 0u;
}

/** Drop the message held under `key`, as a caller does for an
 *  exchange it has abandoned, rather than let it hold its slot until
 *  it expires (fuzznet, inbox 20261122T1804Z, item 2). Answers 1
 *  where one was held, 0 where none was. */
static inline uint32_t situ_pieces_forget(situ_pieces_t *t,
		const uint8_t *key)
{
	for (uint32_t s = 0u; s < t->messages; s++) {
		if (t->slot[s].live != 0u && memcmp(t->slot[s].key, key, 36u) == 0) {
			t->slot[s].live = 0u;
			return 1u;
		}
	}
	return 0u;
}

/** Drop every message whose first piece came `SITU_PIECES_TIMEOUT` ago
 *  or more, by the wrapping clock. Answers how many went. */
static inline uint32_t situ_pieces_expire(situ_pieces_t *t, uint32_t now)
{
	uint32_t gone = 0u;
	for (uint32_t s = 0u; s < t->messages; s++) {
		if (t->slot[s].live != 0u
		    && (int32_t)(now - t->slot[s].deadline) >= 0) {
			t->slot[s].live = 0u;
			gone++;
		}
	}
	return gone;
}

